"use client";

import { Ruler as RulerPrimitive } from "@audio-ui/react";
import { cn } from "@/lib/utils";

/** Mirrors the primitive's own default step count, used only to size the decorative marks when neither value nor defaultValue is passed. */
const DEFAULT_TOTAL_STEPS = 16;
/** Every Nth step gets a taller "beat" mark instead of a plain tick — purely decorative, the primitive itself has no opinion on marks. */
const DEFAULT_STEPS_PER_BEAT = 4;

interface RulerProps extends RulerPrimitive.RootProps {
  /** Shows the playhead part. Position updates far too fast for React state — drive it via `playheadRef`. */
  isPlaying?: boolean;
  playheadRef?: React.RefObject<HTMLDivElement | null>;
  stepsPerBeat?: number;
}

export function Ruler({
  className,
  isPlaying,
  playheadRef,
  stepsPerBeat = DEFAULT_STEPS_PER_BEAT,
  totalSteps = DEFAULT_TOTAL_STEPS,
  ...props
}: RulerProps) {
  return (
    <RulerPrimitive.Root
      className="w-full min-w-0"
      totalSteps={totalSteps}
      {...props}
    >
      <RulerPrimitive.Track
        className={cn(
          "relative h-6 overflow-hidden rounded-4xl border border-transparent bg-card shadow-sm ring-1 ring-foreground/10 transition-[color,border-color,box-shadow,opacity] duration-150 ease-out hover:ring-4 hover:ring-ring/30 has-[:focus-visible]:ring-4 has-[:focus-visible]:ring-ring/30 active:ring-4 active:ring-ring/30 has-[:focus-visible]:border-ring active:border-ring motion-reduce:transition-none relative w-full min-w-0 touch-none select-none overflow-hidden",
          "focus-visible:outline-none",
          "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
          className
        )}
        data-slot="ruler"
      >
        {Array.from({ length: totalSteps }, (_, step) => (
          <div
            className={cn(
              "pointer-events-none bottom-0 h-1.5 bg-border absolute inset-y-0 w-px",
              step % stepsPerBeat === 0 && "h-full bg-border"
            )}
            key={String(step)}
            style={{ left: `${(step / totalSteps) * 100}%` }}
          />
        ))}
        <RulerPrimitive.LoopRegion className="rounded-[min(var(--radius-sm),6px)] bg-primary/25 ring-1 ring-primary/40 transition-[background-color,box-shadow] duration-150 ease-out hover:bg-primary/35 focus-visible:ring-4 focus-visible:ring-ring/30 active:ring-4 active:ring-ring/30 data-[disabled=true]:pointer-events-none motion-reduce:transition-none inset-y-0 cursor-grab touch-none select-none outline-none active:cursor-grabbing">
          <RulerPrimitive.LoopRegionHandle
            className="bg-foreground/20 transition-colors hover:bg-foreground/40 motion-reduce:transition-none inset-y-0 left-0 w-2 cursor-ew-resize"
            side="start"
          />
          <RulerPrimitive.LoopRegionHandle
            className="bg-foreground/20 transition-colors hover:bg-foreground/40 motion-reduce:transition-none inset-y-0 right-0 w-2 cursor-ew-resize"
            side="end"
          />
        </RulerPrimitive.LoopRegion>
        {isPlaying ? (
          <RulerPrimitive.Playhead
            className="bg-foreground inset-y-0 w-px"
            ref={playheadRef}
          />
        ) : null}
      </RulerPrimitive.Track>
    </RulerPrimitive.Root>
  );
}
